function render() {
  if (!todoList) return;

  var filtered = todos.filter(function (todo) {
    if (currentFilter === '/active') return !todo.completed;
    if (currentFilter === '/completed') return todo.completed;
    return true;
  });

  // Map existing li elements by data-id
  var existing = {};
  var existingLis = todoList.querySelectorAll('li[data-id]');
  for (var i = 0; i < existingLis.length; i++) {
    var li = existingLis[i];
    existing[li.dataset.id] = li;
  }

  // Build the correct list, reusing existing DOM nodes
  var seen = {};
  for (var i = 0; i < filtered.length; i++) {
    var todo = filtered[i];
    var id = todo.id;
    seen[id] = true;

    var li = existing[id];
    if (li) {
      // Update existing node in place
      var completedClass = 'view';
      li.className = (todo.completed ? 'completed' : '') + (editingId === id ? ' editing' : '');
      var toggle = li.querySelector('.toggle');
      if (toggle) toggle.checked = todo.completed;
      var label = li.querySelector('label');
      if (label) label.textContent = todo.title;
      var editInput = li.querySelector('.edit');
      if (editInput) editInput.value = todo.title;
    } else {
      // Create new node
      li = document.createElement('li');
      li.dataset.id = id;
      li.className = (todo.completed ? 'completed' : '') + (editingId === id ? ' editing' : '');
      var checkedAttr = todo.completed ? ' checked' : '';
      li.innerHTML = '<div class="view">' +
        '<input class="toggle" type="checkbox"' + checkedAttr + '>' +
        '<label>' + escapeHtml(todo.title) + '</label>' +
        '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + escapeHtml(todo.title) + '">';
    }
    todoList.appendChild(li);
  }

  // Remove nodes not in the filtered list
  for (var i = 0; i < existingLis.length; i++) {
    var li = existingLis[i];
    if (!seen[li.dataset.id]) {
      li.parentNode.removeChild(li);
    }
  }

  updateCount();
  updateToggleAll();
  updateClearCompleted();
  updateMainAndFooter();
  updateFilterLinks();
}

